fragmentShader:
uniform float uT, uF; uniform sampler2D uRain; varying vec3 vW;
      void main(){ vec2 q = vec2(vW.x + vW.z, vW.y) * .45; float r = texture2D(uRain, q + vec2(0., uT * .12)).r, r2 = texture2D(uRain, q * 1.7 + vec2(.31, uT * .27)).r;
        vec3 c = mix(vec3(.03, .05, .08), vec3(.6, .66, .8), min(1., uF)); float a = .22 + uF * .4 + (r * .5 + r2 * .35) * .3;
        gl_FragColor = vec4(c + vec3(.16, .2, .26) * (r + r2) * .55, a); }
